import { z } from 'zod';

export const AddDepartmentDialogSchema = z.object({
    name: z.string().min(1, 'اسم القسم مطلوب'),
    directSupervisor: z.string().min(1, 'المشرف المباشر مطلوب'),
    employeeCount: z
        .string()
        .min(1, 'عدد الموظفين مطلوب')
        .refine((v) => /^\d+$/.test(v), { message: 'أدخل عدداً صحيحاً' })
        .refine((v) => parseInt(v, 10) > 0, { message: 'يجب أن يكون العدد أكبر من صفر' }),
});

export type AddDepartmentDialogFormValues = z.infer<typeof AddDepartmentDialogSchema>;

export const addDepartmentDialogDefaultValues: AddDepartmentDialogFormValues = {
    name: '',
    directSupervisor: '',
    employeeCount: '',
};
