import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { toast } from 'sonner';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import {
    AddDepartmentDialogFormValues,
    AddDepartmentDialogSchema,
    addDepartmentDialogDefaultValues,
} from './add-department-dialog-schema';
import { Textarea } from '@/components/ui/textarea';

interface AddDepartmentDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved?: () => void;
}

export default function AddDepartmentDialog({ open, onOpenChange, onSaved }: AddDepartmentDialogProps) {
    const form = useForm<AddDepartmentDialogFormValues>({
        resolver: zodResolver(AddDepartmentDialogSchema),
        defaultValues: addDepartmentDialogDefaultValues,
    });

    useEffect(() => {
        if (open) {
            form.reset(addDepartmentDialogDefaultValues);
        }
    }, [open]);

    const onSubmit = (_data: AddDepartmentDialogFormValues) => {
        toast.success('تم حفظ القسم بنجاح', { className: 'font-cairo' });
        onSaved?.();
        onOpenChange(false);
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                className="max-w-[920px] max-h-[92vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]"
            >
                <DialogHeader className="flex flex-col items-stretch space-y-0">
                    <div className="flex flex-row items-center gap-2 mb-4">
                        <PlusIcon />
                        <h2 className="text-[22px] font-bold text-primery-blue-500">إضافة قسم</h2>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1]" />
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6 space-y-6">
                        <div className="space-y-5">


                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">

                                <FormField
                                    control={form.control}
                                    name="name"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                                اسم القسم
                                            </FormLabel>
                                            <FormControl>
                                                <Input
                                                    {...field}
                                                    type="text"
                                                    placeholder="ادخل اسم القسم"
                                                    className="placeholder:text-white-blue-600"
                                                />
                                            </FormControl>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                                <FormField
                                    control={form.control}
                                    name="directSupervisor"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                                المشرف المباشر
                                            </FormLabel>
                                            <FormControl>
                                                <Input
                                                    {...field}
                                                    type="text"
                                                    placeholder="ادخل المشرف المباشر"
                                                    className="placeholder:text-white-blue-600"
                                                />
                                            </FormControl>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                            </div>
                            <FormField
                                control={form.control}
                                name="employeeCount"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            عدد الموظفين
                                        </FormLabel>
                                        <FormControl>
                                            <Input
                                                {...field}
                                                type="number"
                                                inputMode="numeric"
                                                placeholder="ادخل عدد الموظفين"
                                                className="placeholder:text-white-blue-600"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="description"
                                className="flex flex-col min-h-[157px]"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            وصف القسم
                                        </FormLabel>
                                        <FormControl>
                                            <Textarea
                                                {...field}
                                                placeholder="ادخل وصف القسم"
                                                className="placeholder:text-white-blue-600"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />

                        </div>

                        <div className="flex flex-row-reverse gap-4 pt-2">
                            <PrimaryButton type="submit" className="flex-1 text-base font-semibold py-3">
                                إضافة
                            </PrimaryButton>
                            <SecondaryButton
                                type="button"
                                className="flex-1 text-base font-semibold py-3"
                                onClick={() => onOpenChange(false)}
                            >
                                إلغاء
                            </SecondaryButton>
                        </div>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}
