import type { ReactNode } from 'react';
import { ColumnDef, Row } from '@tanstack/react-table';
import { useNavigate } from 'react-router-dom';
import EditIcon from '@/components/icons/EditIcon';
import ViewIcon from '@/components/icons/ViewIcon';
import { Department } from '@/types/department.types';
import { cn } from '@/lib/utils';

const headerCell =
    'text-sm px-4 py-3.5 text-primery-blue-600 font-semibold tracking-normal leading-relaxed bg-white-blue-100/90 border-b border-[#E8E7EA]';

const bodyCell = 'text-sm px-4 py-3.5 leading-relaxed align-middle';

function CellText({ children, className }: { children: ReactNode; className?: string }) {
    return (
        <span className={cn('text-[#4B5563] font-medium', className)} dir="auto">
            {children}
        </span>
    );
}

function StatusPill({ children }: { children: ReactNode }) {
    if (children == null || children === '') {
        return <CellText className="text-[#9CA3AF] font-normal">—</CellText>;
    }
    return (
        <span
            className={cn(
                'inline-flex items-center px-2.5 py-1 rounded-md text-xs font-semibold tracking-normal',
                'bg-[#ECFDF5] text-[#047857] border border-[#A7F3D0]',
            )}
        >
            {children}
        </span>
    );
}

const ActionsCell = ({ row }: { row: Row<Department> }) => {
    const navigate = useNavigate();
    const id = row.original.id;

    const btnClass =
        'inline-flex items-center justify-center rounded-lg p-2 text-primery-blue-500 transition-colors hover:bg-primery-blue-50 hover:text-primery-blue-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-primery-blue-400 focus-visible:ring-offset-1';

    return (
        <div className={cn(bodyCell, 'text-end')}>
            <div className="flex flex-row items-center justify-end gap-1">
                <button
                    type="button"
                    onClick={() => navigate(`/human-resources/department/${id}/edit`)}
                    className={btnClass}
                    aria-label="تعديل القسم"
                >
                    <EditIcon width="18" height="18" />
                </button>
                <button
                    type="button"
                    onClick={() => navigate(`/human-resources/department/${id}/edit`)}
                    className={btnClass}
                    aria-label="عرض القسم"
                >
                    <ViewIcon width="18" height="18" />
                </button>
            </div>
        </div>
    );
};

function display(v: unknown) {
    if (v == null || v === '') return '—';
    return String(v);
}

export const columns: ColumnDef<Department>[] = [
    {
        accessorKey: 'id',
        header: () => <div className={headerCell}>القسم</div>,
        cell: ({ row }) => (
            <div className={bodyCell}>
                <span className="font-semibold text-primery-blue-800 tracking-normal">{row.original.name}</span>
            </div>
        ),
    },
    {
        accessorKey: 'name',
        header: () => <div className={headerCell}>المشرف المباشر</div>,
        cell: ({ row }) => (
            <div className={bodyCell}>
                <CellText>{display(row.original.position)}</CellText>
            </div>
        ),
    },
    {
        accessorKey: 'status',
        header: () => <div className={cn(headerCell, 'text-nowrap')}>عدد الموظفين</div>,
        cell: () => (
            <div className={bodyCell}>
                <CellText className="tabular-nums">—</CellText>
            </div>
        ),
    },
    {
        accessorKey: 'date',
        header: () => <div className={cn(headerCell, 'text-nowrap')}>الحد الأقصى</div>,
        cell: ({ row }) => (
            <div className={bodyCell}>
                <CellText className="tabular-nums">{display(row.original.employee_number)}</CellText>
            </div>
        ),
    },
    {
        accessorKey: 'location',
        header: () => <div className={cn(headerCell, 'text-nowrap')}>حالة العمل</div>,
        cell: ({ row }) => (
            <div className={bodyCell}>
                <StatusPill>{row.original.contract_type}</StatusPill>
            </div>
        ),
    },
    {
        id: 'actions',
        header: () => (
            <div className={cn(headerCell, 'text-center w-[120px] min-w-[120px]')}>إجراءات</div>
        ),
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
