import { Card } from '@/types/statistics';
import UserRemoveIcon from '@/components/icons/user/UserRemove';
import GroupIcon from '@/components/icons/user/GroupIcon';
import { useEffect, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { DepartmentsStats } from '../../types/departmentsStats.types';
import DepartmentsList from '../../components/departmentsList/DepartmentsList';
import DepartmentsStatistics from '../../components/statistics/DepartmentsStatistics';

export default function DepartmentsPage() {
    const [stats, setStats] = useState<DepartmentsStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.departments.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي القسم', num: stats?.total_departments, percent: 12, icon: <GroupIcon /> },
        { text: 'اجمالي الموظفين', num: stats?.total_employees, percent: 0, icon: <UserRemoveIcon /> },
        // { text: 'القسم دوام كلي', num: stats?.total_full_time_departments, percent: -0.3, icon: <TwoUsersIcon /> },
        // { text: 'القسم دوام جزئي', num: stats?.total_part_time_departments, percent: -0.3, icon: <MinusUserIcon /> },
    ];

    return (
        <div className="w-full mt-6 mb-20">
            <DepartmentsStatistics cards={cards} />
            <DepartmentsList />
        </div>
    );
}
