import { Table } from '@tanstack/react-table';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import AddIcon from '@/components/icons/AddIcon';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { Link } from 'react-router-dom';
import { Filters } from '@/types/table.types';
import { Employee } from '@/types/employee.types';
import ExportToPDF from './ExportToPDF';
import { cn } from '@/lib/utils';
import AddDepartmentDialog from './AddDepartmentDialog';
import { useState } from 'react';

interface DataTableToolbarProps {
    table: Table<Employee>;
    globalFilter: string;
    setGlobalFilter: (value: string) => void;
    filters: Filters;
    setFilters: (value: Filters) => void;
    data: any[];
}

export function DataTableToolbar({ globalFilter, setGlobalFilter, filters, setFilters, data }: DataTableToolbarProps) {
    const [addDepartmentOpen, setAddDepartmentOpen] = useState(false);
    return (
        <>
            <AddDepartmentDialog open={addDepartmentOpen} onOpenChange={setAddDepartmentOpen} />
            <div className="flex flex-col gap-4 p-3 sm:p-4 sm:flex-row sm:items-center sm:justify-between bg-white-blue-50/80 rounded-t-xl border-b border-[#E8E7EA]">
                <UnderlineHeading text="قائمة الأقسام" className="text-start" />
                <div className="flex flex-col sm:flex-row flex-wrap items-stretch sm:items-center gap-3">
                    <div
                        className={cn(
                            'flex flex-row items-center min-w-0 w-full sm:w-[280px] h-10 px-3 rounded-lg',
                            'border border-[#E0E4EB] bg-white shadow-sm',
                            'transition-shadow focus-within:border-primery-blue-300 focus-within:ring-2 focus-within:ring-primery-blue-100',
                        )}
                    >
                        <Input
                            placeholder="ابحث باسم القسم"
                            value={globalFilter}
                            onChange={(event) => setGlobalFilter(event.target.value)}
                            className="flex-1 min-w-0 text-primery-blue-900 p-0 h-auto text-sm border-none shadow-none focus-visible:ring-0 placeholder:text-[#90868C]"
                        />
                        <button
                            type="button"
                            className="shrink-0 p-1 rounded-md text-primery-blue-500 hover:bg-primery-blue-50 transition-colors"
                            aria-label="بحث"
                        >
                            <SearchIcon className="text-primery-blue-600" />
                        </button>
                    </div>
                    <div className="flex flex-row items-center gap-3 flex-wrap">
                        <CustomSelect
                            value={(filters?.status as string) || ''}
                            onValueChange={(value) => {
                                setFilters({ ...filters, status: value });
                            }}
                            placeholder="فلتر"
                            width="min-w-[100px]"
                            options={[
                                { label: 'الكل', value: '' },
                                { label: 'متاح', value: 'active' },
                                { label: 'غير متاح', value: 'not active' },
                            ]}
                        />
                        <PrimaryButton
                            asChild
                            className="text-sm px-4 py-2.5 h-auto font-semibold font-cairo shadow-sm"
                        >
                            <button type="button" onClick={() => setAddDepartmentOpen(true)}>
                                <AddIcon />
                                <span className="text-xs font-medium leading-snug">إضافة قسم</span>
                            </button>
                        </PrimaryButton>
                        <ExportToPDF data={data} />
                    </div>
                </div>
            </div>
        </>
    );
}
